using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;using Newtonsoft.Json;
public static class PerimeterAudit {
 static string PathOf(Transform t)=>t.parent?PathOf(t.parent)+"/"+t.name:t.name;
 public static object Run(){var s=SceneManager.GetActiveScene();if(s.isDirty||Application.isPlaying)throw new Exception("Saved edit scene required");var root=s.GetRootGameObjects().Single(g=>g.name.StartsWith("B5_Circular")).transform;var room=root.Find("C01_Experiment_Art");var bank=room.Find("C01_Perimeter_Lab");Physics.SyncTransforms();var overlaps=new List<object>();var boxes=bank.GetComponentsInChildren<BoxCollider>().Where(c=>c.enabled).ToArray();
 foreach(var box in boxes)foreach(var c in Physics.OverlapBox(box.bounds.center,box.bounds.extents,Quaternion.identity,~0,QueryTriggerInteraction.Ignore).Where(c=>c!=box&&!c.transform.IsChildOf(box.transform)&&c.transform.IsChildOf(root)&&!c.name.Contains("Floor"))){Vector3 d;float dep;if(Physics.ComputePenetration(box,box.transform.position,box.transform.rotation,c,c.transform.position,c.transform.rotation,out d,out dep)&&dep>.035f)overlaps.Add(new{a=PathOf(box.transform),b=PathOf(c.transform),depth=dep});}
 var circleBlocked=new List<object>();int samples=0;
 foreach(float radius in new[]{5.0f,5.7f,6.4f})for(int angle=0;angle<360;angle+=2){float a=angle*Mathf.Deg2Rad;var p=room.position+new Vector3(radius*Mathf.Cos(a),0,radius*Mathf.Sin(a));samples++;var hits=Physics.OverlapCapsule(p+Vector3.up*.36f,p+Vector3.up*1.52f,.28f,~0,QueryTriggerInteraction.Ignore).Where(c=>c.transform.IsChildOf(root)&&!c.name.Contains("Floor")).ToArray();if(hits.Length>0)circleBlocked.Add(new{radius,angle,hits=hits.Select(c=>PathOf(c.transform)).ToArray()});}
 var oldStyle=root.GetComponentsInChildren<MeshFilter>().Where(m=>Vector3.Distance(m.GetComponent<Renderer>().bounds.center,room.position)<12&&!m.name.StartsWith("CP_")&&!AssetDatabase.GetAssetPath(m.sharedMesh).Contains("Environment")).Select(m=>new{path=PathOf(m.transform),mesh=AssetDatabase.GetAssetPath(m.sharedMesh),bounds=m.GetComponent<Renderer>().bounds.ToString()}).ToArray();
 var result=new{stations=bank.Cast<Transform>().Count(t=>t.name.StartsWith("Station_")),newFloorColliders=boxes.Length,overlaps,circleSamples=samples,circleBlocked,oldStyle,inspectionBoxes=root.GetComponentsInChildren<Transform>().Where(t=>t.name.Contains("InspectionBox")&&Vector3.Distance(t.position,room.position)<12).Select(t=>PathOf(t)).ToArray(),missingMaterials=bank.GetComponentsInChildren<Renderer>().Where(r=>r.sharedMaterials.Any(m=>!m||!m.shader||m.shader.name=="Hidden/InternalErrorShader")).Select(r=>PathOf(r.transform)).ToArray()};string dir=Path.GetFullPath(Path.Combine(Application.dataPath,"../../../SourceAssets/C01_InstrumentDetail/"));File.WriteAllText(dir+"audit.json",JsonConvert.SerializeObject(result,Formatting.Indented));return new{result.stations,result.newFloorColliders,overlaps=overlaps.Count,circleBlocked=circleBlocked.Count,result.inspectionBoxes,result.missingMaterials};}
}
